/**
 * `@pantoken/plugin-cleanup-orphans` — Filter out orphaned tokens from upstream sources.
 *
 * Removes tokens that are defined in the upstream source but are unused in pantoken's
 * component layer, typically due to upstream typos or incomplete migrations.
 *
 * @example
 * ```ts
 * import { buildTokens } from "@pantoken/core/build";
 * import { cleanupOrphans } from "@pantoken/plugin-cleanup-orphans";
 *
 * const tokens = buildTokens({ theme: "rebrand", plugins: [cleanupOrphans()] });
 * ```
 *
 * @module
 * @beta
 */
import { definePlugin } from "@pantoken/plugin-kit";
import type { PantokenPlugin } from "@pantoken/model";

/** Tokens to remove due to being orphaned or duplicates with typos from upstream sources. */
const ORPHANED_TOKEN_PATTERNS = [
  // v2.6.0 upstream typo: side-nav-bar has tokens named with "insitution" (missing 'i' in institution)
  // These are not referenced by any components and have no corrected counterpart in the IR.
  "--instui-component-side-nav-bar-new-insitution-logo-gap",
  "--instui-component-side-nav-bar-new-insitution-logo-padding",
];

/**
 * Create the cleanup orphans plugin.
 *
 * Filters out tokens that exist in the upstream source but are unused in pantoken's
 * component layer due to upstream quality issues.
 *
 * @returns A {@link PantokenPlugin} with a `tokens` hook.
 */
export function cleanupOrphans(): PantokenPlugin {
  return definePlugin({
    name: "@pantoken/plugin-cleanup-orphans",
    tokens: ({ tokens }) =>
      tokens.filter((token) => !ORPHANED_TOKEN_PATTERNS.includes(token.name ?? "")),
  });
}

export default cleanupOrphans;

